import{_ as d,a0 as l,w as o,s as p,I as t,x as e,a1 as i,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"怎樣用 Bash 編程：邏輯操作符和 shell 擴展 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣用 Bash 編程：邏輯操作符和 shell 擴展 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣用 Bash 編程：邏輯操作符和 shell 擴展 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣用 Bash 編程：邏輯操作符和 shell 擴展 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191022 How to program with Bash- Logical operators and shell expansions","title":"怎樣用 Bash 編程：邏輯操作符和 shell 擴展","tag":"201912","desc":""},"relativePath":"201912/20191022 How to program with Bash- Logical operators and shell expansions.md","filePath":"[post].md"}'),c={name:"201912/20191022 How to program with Bash- Logical operators and shell expansions.md"};function h(u,s,g,k,b,f){const a=l("Link");return o(),p("div",null,[s[26]||(s[26]=t("h1",{id:"怎樣用-bash-編程-邏輯操作符和-shell-擴展",tabindex:"-1"},[e("怎樣用 Bash 編程：邏輯操作符和 shell 擴展 "),t("a",{class:"header-anchor",href:"#怎樣用-bash-編程-邏輯操作符和-shell-擴展","aria-label":"Permalink to “怎樣用 Bash 編程：邏輯操作符和 shell 擴展”"},"​")],-1)),s[27]||(s[27]=t("blockquote",null,[t("p",null,"學習邏輯操作符和 shell 擴展，本文是三篇 Bash 編程系列的第二篇。")],-1)),s[28]||(s[28]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/17/173459pxhz0aiicimzd1m2.jpg",alt:""})],-1)),t("p",null,[s[1]||(s[1]=e("Bash 是一種強大的編程語言，完美契合命令列和 shell 腳本。本系列（三篇文章，基於我的 ",-1)),i(a,{href:"http://www.both.org/?page_id=1183"},{default:n(()=>[...s[0]||(s[0]=[e("三集 Linux 自學課程",-1)])]),_:1}),s[2]||(s[2]=e("）講解如何在 CLI 使用 Bash 編程。",-1))]),t("p",null,[i(a,{href:"https://linux.cn/article-11552-1.html"},{default:n(()=>[...s[3]||(s[3]=[e("第一篇文章",-1)])]),_:1}),s[4]||(s[4]=e(" 講解了 Bash 的一些簡單命令列操作，包括如何使用變量和控制操作符。第二篇文章探討文件、字符串、數字等類型和各種各樣在執行流中提供控制邏輯的的邏輯運算符，還有 Bash 中的各類 shell 擴展。本系列第三篇也是最後一篇文章，將會探索能重複執行操作的 ",-1)),s[5]||(s[5]=t("code",null,"for",-1)),s[6]||(s[6]=e(" 、",-1)),s[7]||(s[7]=t("code",null,"while",-1)),s[8]||(s[8]=e(" 和 ",-1)),s[9]||(s[9]=t("code",null,"until",-1)),s[10]||(s[10]=e(" 循環。",-1))]),s[29]||(s[29]=r(`<p>邏輯操作符是程序中進行判斷的根本要素，也是執行不同的語句組合的依據。有時這也被稱為流控制。</p><h3 id="邏輯操作符" tabindex="-1">邏輯操作符 <a class="header-anchor" href="#邏輯操作符" aria-label="Permalink to “邏輯操作符”">​</a></h3><p>Bash 中有大量的用於不同條件表達式的邏輯操作符。最基本的是 <code>if</code> 控制結構，它判斷一個條件，如果條件為真，就執行一些程序語句。操作符共有三類：文件、數字和非數字操作符。如果條件為真，所有的操作符返回真值（<code>0</code>），如果條件為假，返回假值（<code>1</code>）。</p><p>這些比較操作符的函數語法是，一個操作符加一個或兩個參數放在中括號內，後面跟一系列程序語句，如果條件為真，程序語句執行，可能會有另一個程序語句列表，該列表在條件為假時執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ arg1 operator arg2 ] ; then list</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>if [ arg1 operator arg2 ] ; then list ; else list ; fi</span></span></code></pre></div><p>像例子中那樣，在比較表達式中，空格不能省略。中括號的每部分，<code>[</code> 和 <code>]</code>，是跟 <code>test</code> 命令一樣的傳統的 Bash 符號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if test arg1 operator arg2 ; then list</span></span></code></pre></div><p>還有一個更新的語法能提供一點點便利，一些系統管理員比較喜歡用。這種格式對於不同版本的 Bash 和一些 shell 如 ksh（Korn shell）兼容性稍差。格式如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [[ arg1 operator arg2 ]] ; then list</span></span></code></pre></div><h4 id="文件操作符" tabindex="-1">文件操作符 <a class="header-anchor" href="#文件操作符" aria-label="Permalink to “文件操作符”">​</a></h4><p>文件操作符是 Bash 中一系列強大的邏輯操作符。圖表 1 列出了 20 多種不同的 Bash 處理文件的操作符。在我的腳本中使用頻率很高。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-a filename</code></td><td>如果文件存在，返回真值；文件可以為空也可以有內容，但是隻要它存在，就返回真值</td></tr><tr><td><code>-b filename</code></td><td>如果文件存在且是一個塊設備，如 <code>/dev/sda</code> 或 <code>/dev/sda1</code>，則返回真值</td></tr><tr><td><code>-c filename</code></td><td>如果文件存在且是一個字符設備，如 <code>/dev/TTY1</code>，則返回真值</td></tr><tr><td><code>-d filename</code></td><td>如果文件存在且是一個目錄，返回真值</td></tr><tr><td><code>-e filename</code></td><td>如果文件存在，返回真值；與上面的 <code>-a</code> 相同</td></tr><tr><td><code>-f filename</code></td><td>如果文件存在且是一個一般文件，不是目錄、設備文件或鏈接等的其他的文件，則返回 真值</td></tr><tr><td><code>-g filename</code></td><td>如果文件存在且 <code>SETGID</code> 標記被設置在其上，返回真值</td></tr><tr><td><code>-h filename</code></td><td>如果文件存在且是一個符號鏈接，則返回真值</td></tr><tr><td><code>-k filename</code></td><td>如果文件存在且粘滯位已設置，則返回真值</td></tr><tr><td><code>-p filename</code></td><td>如果文件存在且是一個命名的管道（FIFO），返回真值</td></tr><tr><td><code>-r filename</code></td><td>如果文件存在且有可讀權限（它的可讀位被設置），返回真值</td></tr><tr><td><code>-s filename</code></td><td>如果文件存在且大小大於 0，返回真值；如果一個文件存在但大小為 0，則返回假值</td></tr><tr><td><code>-t fd</code></td><td>如果文件描述符 <code>fd</code> 被打開且被關聯到一個終端設備上，返回真值</td></tr><tr><td><code>-u filename</code></td><td>如果文件存在且它的 <code>SETUID</code> 位被設置，返回真值</td></tr><tr><td><code>-w filename</code></td><td>如果文件存在且有可寫權限，返回真值</td></tr><tr><td><code>-x filename</code></td><td>如果文件存在且有可執行權限，返回真值</td></tr><tr><td><code>-G filename</code></td><td>如果文件存在且文件的組 ID 與當前用户相同，返回真值</td></tr><tr><td><code>-L filename</code></td><td>如果文件存在且是一個符號鏈接，返回真值（同 <code>-h</code>）</td></tr><tr><td><code>-N filename</code></td><td>如果文件存在且從文件上一次被讀取後文件被修改過，返回真值</td></tr><tr><td><code>-O filename</code></td><td>如果文件存在且你是文件的擁有者，返回真值</td></tr><tr><td><code>-S filename</code></td><td>如果文件存在且文件是套接字，返回真值</td></tr><tr><td><code>file1 -ef file2</code></td><td>如果文件 <code>file1</code> 和文件 <code>file2</code> 指向同一設備的同一 INODE 號，返回真值（即硬鏈接）</td></tr><tr><td><code>file1 -nt file2</code></td><td>如果文件 <code>file1</code> 比 <code>file2</code> 新（根據修改日期），或 <code>file1</code> 存在而 <code>file2</code> 不存在，返回真值</td></tr><tr><td><code>file1 -ot file2</code></td><td>如果文件 <code>file1</code> 比 <code>file2</code> 舊（根據修改日期），或 <code>file1</code> 不存在而 <code>file2</code> 存在</td></tr></tbody></table></div><p><em>圖表 1：Bash 文件操作符</em></p><p>以測試一個文件存在與否來舉例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -e $File ] ; then echo &quot;The file $File exists.&quot; ; else echo &quot;The file $File does not exist.&quot; ; fi</span></span>
<span class="line"><span>The file TestFile1 does not exist.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>創建一個用來測試的文件，命名為 <code>TestFile1</code>。目前它不需要包含任何數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ touch TestFile1</span></span></code></pre></div><p>在這個簡短的 CLI 程序中，修改 <code>$File</code> 變量的值相比於在多個地方修改表示文件名的字符串的值要容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -e $File ] ; then echo &quot;The file $File exists.&quot; ; else echo &quot;The file $File does not exist.&quot; ; fi</span></span>
<span class="line"><span>The file TestFile1 exists.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>現在，運行一個測試來判斷一個文件是否存在且長度不為 0（表示它包含數據）。假設你想判斷三種情況：</p><ol><li>文件不存在；</li><li>文件存在且為空；</li><li>文件存在且包含數據。</li></ol><p>因此，你需要一組更復雜的測試代碼 — 為了測試所有的情況，使用 <code>if-elif-else</code> 結構中的 <code>elif</code> 語句：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; fi</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>在這個情況中，文件存在但不包含任何數據。向文件添加一些數據再運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is file $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>這組語句能返回正常的結果，但是僅僅是在我們已知三種可能的情況下測試某種確切的條件。添加一段 <code>else</code> 語句，這樣你就可以更精確地測試。把文件刪掉，你就可以完整地測試這段新代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; rm $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 does not exist or is empty.</span></span></code></pre></div><p>現在創建一個空文件用來測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; touch $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 does not exist or is empty.</span></span></code></pre></div><p>向文件添加一些內容，然後再測試一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is file $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span></code></pre></div><p>現在加入 <code>elif</code> 語句來辨別是文件不存在還是文件為空：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; touch $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; elif [ -e $File ] ; then echo &quot;$File exists and is empty.&quot; ; else echo &quot;$File does not exist.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and is empty.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; elif [ -e $File ] ; then echo &quot;$File exists and is empty.&quot; ; else echo &quot;$File does not exist.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>現在你有一個可以測試這三種情況的 Bash CLI 程序，但是可能的情況是無限的。</p><p>如果你能像保存在文件中的腳本那樣組織程序語句，那麼即使對於更復雜的命令組合也會很容易看出它們的邏輯結構。圖表 2 就是一個示例。 <code>if-elif-else</code> 結構中每一部分的程序語句的縮進讓邏輯更變得清晰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>File=&quot;TestFile1&quot;</span></span>
<span class="line"><span>echo &quot;This is $File&quot; &gt; $File</span></span>
<span class="line"><span>if [ -s $File ]</span></span>
<span class="line"><span>   then</span></span>
<span class="line"><span>   echo &quot;$File exists and contains data.&quot;</span></span>
<span class="line"><span>elif [ -e $File ]</span></span>
<span class="line"><span>   then</span></span>
<span class="line"><span>   echo &quot;$File exists and is empty.&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>   echo &quot;$File does not exist.&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><em>圖表 2: 像在腳本里一樣重寫書寫命令列程序</em></p><p>對於大多數 CLI 程序來説，讓這些複雜的命令變得有邏輯需要寫很長的代碼。雖然 CLI 可能是用 Linux 或 Bash 內置的命令，但是當 CLI 程序很長或很複雜時，創建一個保存在文件中的腳本將更有效，保存到文件中後，可以隨時運行。</p><h4 id="字符串比較操作符" tabindex="-1">字符串比較操作符 <a class="header-anchor" href="#字符串比較操作符" aria-label="Permalink to “字符串比較操作符”">​</a></h4><p>字符串比較操作符使我們可以對字符串中的字符按字母順序進行比較。圖表 3 列出了僅有的幾個字符串比較操作符。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-z string</code></td><td>如果字符串的長度為 0 ，返回真值</td></tr><tr><td><code>-n string</code></td><td>如果字符串的長度不為 0 ，返回真值</td></tr><tr><td><code>string1 == string2</code> 或 <code>string1 = string2</code></td><td>如果兩個字符串相等，返回真值。處於遵從 POSIX 一致性，在測試命令中應使用一個等號 <code>=</code>。與命令 <code>[[</code> 一起使用時，會進行如上描述的模式匹配（混合命令）。</td></tr><tr><td><code>string1 != string2</code></td><td>兩個字符串不相等，返回真值</td></tr><tr><td><code>string1 &lt; string2</code></td><td>如果對 <code>string1</code> 和 <code>string2</code> 按字母順序進行排序，<code>string1</code> 排在 <code>string2</code> 前面（即基於地區設定的對所有字母和特殊字符的排列順序）</td></tr><tr><td><code>string1 &gt; string2</code></td><td>如果對 <code>string1</code> 和 <code>string2</code> 按字母順序進行排序，<code>string1</code> 排在 <code>string2</code> 後面</td></tr></tbody></table></div><p><em>圖表 3: Bash 字符串邏輯操作符</em></p><p>首先，檢查字符串長度。比較表達式中 <code>$MyVar</code> 兩邊的雙引號不能省略（你仍應該在目錄 <code>~/testdir</code> 下 ）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; if [ -z &quot;&quot; ] ; then echo &quot;MyVar is zero length.&quot; ; else echo &quot;MyVar contains data&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;Random text&quot; ; if [ -z &quot;&quot; ] ; then echo &quot;MyVar is zero length.&quot; ; else echo &quot;MyVar contains data&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length.</span></span></code></pre></div><p>你也可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;Random text&quot; ; if [ -n &quot;$MyVar&quot; ] ; then echo &quot;MyVar contains data.&quot; ; else echo &quot;MyVar is zero length&quot; ; fi</span></span>
<span class="line"><span>MyVar contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; if [ -n &quot;$MyVar&quot; ] ; then echo &quot;MyVar contains data.&quot; ; else echo &quot;MyVar is zero length&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length</span></span></code></pre></div><p>有時候你需要知道一個字符串確切的長度。這雖然不是比較，但是也與比較相關。不幸的是，計算字符串的長度沒有簡單的方法。有很多種方法可以計算，但是我認為使用 <code>expr</code>（求值表達式）命令是相對最簡單的一種。閲讀 <code>expr</code> 的手冊頁可以瞭解更多相關知識。注意表達式中你檢測的字符串或變量兩邊的引號不要省略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; expr length &quot;$MyVar&quot;</span></span>
<span class="line"><span>0</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;How long is this?&quot; ; expr length &quot;$MyVar&quot;</span></span>
<span class="line"><span>17</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ expr length &quot;We can also find the length of a literal string as well as a variable.&quot;</span></span>
<span class="line"><span>70</span></span></code></pre></div><p>關於比較操作符，在我們的腳本中使用了大量的檢測兩個字符串是否相等（例如，兩個字符串是否實際上是同一個字符串）的操作。我使用的是非 POSIX 版本的比較表達式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ Var1=&quot;Hello World&quot; ; Var2=&quot;Hello World&quot; ; if [ &quot;$Var1&quot; == &quot;$Var2&quot; ] ; then echo &quot;Var1 matches Var2&quot; ; else echo &quot;Var1 and Var2 do not match.&quot; ; fi</span></span>
<span class="line"><span>Var1 matches Var2</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=&quot;Hello World&quot; ; Var2=&quot;Hello world&quot; ; if [ &quot;$Var1&quot; == &quot;$Var2&quot; ] ; then echo &quot;Var1 matches Var2&quot; ; else echo &quot;Var1 and Var2 do not match.&quot; ; fi</span></span>
<span class="line"><span>Var1 and Var2 do not match.</span></span></code></pre></div><p>在你自己的腳本中去試一下這些操作符。</p><h4 id="數字比較操作符" tabindex="-1">數字比較操作符 <a class="header-anchor" href="#數字比較操作符" aria-label="Permalink to “數字比較操作符”">​</a></h4><p>數字操作符用於兩個數字參數之間的比較。像其他類操作符一樣，大部分都很容易理解。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>arg1 -eq arg2</code></td><td>如果 <code>arg1</code> 等於 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -ne arg2</code></td><td>如果 <code>arg1</code> 不等於 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -lt arg2</code></td><td>如果 <code>arg1</code> 小於 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -le arg2</code></td><td>如果 <code>arg1</code> 小於或等於 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -gt arg2</code></td><td>如果 <code>arg1</code> 大於 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -ge arg2</code></td><td>如果 <code>arg1</code> 大於或等於 <code>arg2</code>，返回真值</td></tr></tbody></table></div><p><em>圖表 4: Bash 數字比較邏輯操作符</em></p><p>來看幾個簡單的例子。第一個示例設置變量 <code>$X</code> 的值為 1，然後檢測 <code>$X</code> 是否等於 1。第二個示例中，<code>$X</code> 被設置為 0，所以比較表達式返回結果不為真值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ X=1 ; if [ $X -eq 1 ] ; then echo &quot;X equals 1&quot; ; else echo &quot;X does not equal 1&quot; ; fi</span></span>
<span class="line"><span>X equals 1</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ X=0 ; if [ $X -eq 1 ] ; then echo &quot;X equals 1&quot; ; else echo &quot;X does not equal 1&quot; ; fi</span></span>
<span class="line"><span>X does not equal 1</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>自己來多嘗試一下其他的。</p><h4 id="雜項操作符" tabindex="-1">雜項操作符 <a class="header-anchor" href="#雜項操作符" aria-label="Permalink to “雜項操作符”">​</a></h4><p>這些雜項操作符展示一個 shell 選項是否被設置，或一個 shell 變量是否有值，但是它不顯示變量的值，只顯示它是否有值。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-o optname</code></td><td>如果一個 shell 選項 <code>optname</code> 是啓用的（查看內建在 Bash 手冊頁中的 set <code>-o</code> 選項描述下面的選項列表），則返回真值</td></tr><tr><td><code>-v varname</code></td><td>如果 shell 變量 <code>varname</code> 被設置了值（被賦予了值），則返回真值</td></tr><tr><td><code>-R varname</code></td><td>如果一個 shell 變量 <code>varname</code> 被設置了值且是一個名字引用，則返回真值</td></tr></tbody></table></div><p><em>圖表 5: 雜項 Bash 邏輯操作符</em></p><p>自己來使用這些操作符實踐下。</p><h3 id="擴展" tabindex="-1">擴展 <a class="header-anchor" href="#擴展" aria-label="Permalink to “擴展”">​</a></h3><p>Bash 支持非常有用的幾種類型的擴展和命令替換。根據 Bash 手冊頁，Bash 有七種擴展格式。本文只介紹其中五種：<code>~</code> 擴展、算術擴展、路徑名稱擴展、大括號擴展和命令替換。</p><h4 id="大括號擴展" tabindex="-1">大括號擴展 <a class="header-anchor" href="#大括號擴展" aria-label="Permalink to “大括號擴展”">​</a></h4><p>大括號擴展是生成任意字符串的一種方法。（下面的例子是用特定模式的字符創建大量的文件。）大括號擴展可以用於產生任意字符串的列表，並把它們插入一個用靜態字符串包圍的特定位置或靜態字符串的兩端。這可能不太好想像，所以還是來實踐一下。</p><p>首先，看一下大括號擴展的作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo {string1,string2,string3}</span></span>
<span class="line"><span>string1 string2 string3</span></span></code></pre></div><p>看起來不是很有用，對吧？但是用其他方式使用它，再來看看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Hello &quot;{David,Jen,Rikki,Jason}.</span></span>
<span class="line"><span>Hello David. Hello Jen. Hello Rikki. Hello Jason.</span></span></code></pre></div><p>這看起來貌似有點用了 — 我們可以少打很多字。現在試一下這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo b{ed,olt,ar}s</span></span>
<span class="line"><span>beds bolts bars</span></span></code></pre></div><p>我可以繼續舉例，但是你應該已經理解了它的用處。</p><h4 id="擴展-1" tabindex="-1">~ 擴展 <a class="header-anchor" href="#擴展-1" aria-label="Permalink to “~ 擴展”">​</a></h4><p>資料顯示，使用最多的擴展是波浪字符（<code>~</code>）擴展。當你在命令中使用它（如 <code>cd ~/Documents</code>）時，Bash shell 把這個快捷方式展開成用户的完整的家目錄。</p><p>使用這個 Bash 程序觀察 <code>~</code> 擴展的作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo ~</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo ~/Documents</span></span>
<span class="line"><span>/home/student/Documents</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=~/Documents ; echo $Var1 ; cd $Var1</span></span>
<span class="line"><span>/home/student/Documents</span></span>
<span class="line"><span>[student@studentvm1 Documents]$</span></span></code></pre></div><h4 id="路徑名稱擴展" tabindex="-1">路徑名稱擴展 <a class="header-anchor" href="#路徑名稱擴展" aria-label="Permalink to “路徑名稱擴展”">​</a></h4><p>路徑名稱擴展是展開文件通配模式為匹配該模式的完整路徑名稱的另一種説法，匹配字符使用 <code>?</code> 和 <code>*</code>。文件通配指的是在大量操作中匹配文件名、路徑和其他字符串時用特定的模式字符產生極大的靈活性。這些特定的模式字符允許匹配字符串中的一個、多個或特定字符。</p><ul><li><code>?</code> — 匹配字符串中特定位置的一個任意字符</li><li><code>*</code> — 匹配字符串中特定位置的 0 個或多個任意字符</li></ul><p>這個擴展用於匹配路徑名稱。為了弄清它的用法，請確保 <code>testdir</code> 是當前工作目錄（<code>PWD</code>），先執行基本的列出清單命令 <code>ls</code>（我家目錄下的內容跟你的不一樣）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ls</span></span>
<span class="line"><span>chapter6  cpuHog.dos    dmesg1.txt  Documents  Music       softlink1  testdir6    Videos</span></span>
<span class="line"><span>chapter7  cpuHog.Linux  dmesg2.txt  Downloads  Pictures    Templates  testdir</span></span>
<span class="line"><span>testdir  cpuHog.mac    dmesg3.txt  file005    Public      testdir    tmp</span></span>
<span class="line"><span>cpuHog     Desktop       dmesg.txt   link3      random.txt  testdir1   umask.test</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>現在列出以 <code>Do</code>、<code>testdir/Documents</code> 和 <code>testdir/Downloads</code> 開頭的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Documents:</span></span>
<span class="line"><span>Directory01  file07  file15        test02  test10  test20      testfile13  TextFiles</span></span>
<span class="line"><span>Directory02  file08  file16        test03  test11  testfile01  testfile14</span></span>
<span class="line"><span>file01       file09  file17        test04  test12  testfile04  testfile15</span></span>
<span class="line"><span>file02       file10  file18        test05  test13  testfile05  testfile16</span></span>
<span class="line"><span>file03       file11  file19        test06  test14  testfile09  testfile17</span></span>
<span class="line"><span>file04       file12  file20        test07  test15  testfile10  testfile18</span></span>
<span class="line"><span>file05       file13  Student1.txt  test08  test16  testfile11  testfile19</span></span>
<span class="line"><span>file06       file14  test01        test09  test18  testfile12  testfile20</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Downloads:</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>然而，並沒有得到你期望的結果。它列出了以 <code>Do</code> 開頭的目錄下的內容。使用 <code>-d</code> 選項，僅列出目錄而不列出它們的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ls -d Do*</span></span>
<span class="line"><span>Documents  Downloads</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>在兩個例子中，Bash shell 都把 <code>Do*</code> 模式展開成了匹配該模式的目錄名稱。但是如果有文件也匹配這個模式，會發生什麼？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ touch Downtown ; ls -d Do*</span></span>
<span class="line"><span>Documents  Downloads  Downtown</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>因此所有匹配這個模式的文件也被展開成了完整名字。</p><h4 id="命令替換" tabindex="-1">命令替換 <a class="header-anchor" href="#命令替換" aria-label="Permalink to “命令替換”">​</a></h4><p>命令替換是讓一個命令的標準輸出數據流被當做參數傳給另一個命令的擴展形式，例如，在一個循環中作為一系列被處理的項目。Bash 手冊頁顯示：“命令替換可以讓你用一個命令的輸出替換為命令的名字。”這可能不太好理解。</p><p>命令替換有兩種格式：\`command\` 和 <code>$(command)</code>。在更早的格式中使用反引號（\`），在命令中使用反斜槓（<code>\\</code>）來保持它轉義之前的文本含義。然而，當用在新版本的括號格式中時，反斜槓被當做一個特殊字符處理。也請注意帶括號的格式打開個關閉命令語句都是用一個括號。</p><p>我經常在命令列程序和腳本中使用這種能力，一個命令的結果能被用作另一個命令的參數。</p><p>來看一個非常簡單的示例，這個示例使用了這個擴展的兩種格式（再一次提醒，確保 <code>testdir</code> 是當前工作目錄）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Todays date is \`date\`&quot;</span></span>
<span class="line"><span>Todays date is Sun Apr  7 14:42:46 EDT 2019</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Todays date is $(date)&quot;</span></span>
<span class="line"><span>Todays date is Sun Apr  7 14:42:59 EDT 2019</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p><code>-seq</code> 工具用於一個數字序列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ seq 5</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo \`seq 5\`</span></span>
<span class="line"><span>1 2 3 4 5</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>現在你可以做一些更有用處的操作，比如創建大量用於測試的空文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ for I in $(seq -w 5000) ; do touch file-$I ; done</span></span></code></pre></div><p><code>seq</code> 工具加上 <code>-w</code> 選項後，在生成的數字前面會用 0 補全，這樣所有的結果都等寬，例如，忽略數字的值，它們的位數一樣。這樣在對它們按數字順序進行排列時很容易。</p><p><code>seq -w 5000</code> 語句生成了 1 到 5000 的數字序列。通過把命令替換用於 <code>for</code> 語句，<code>for</code> 語句就可以使用該數字序列來生成文件名的數字部分。</p><h4 id="算術擴展" tabindex="-1">算術擴展 <a class="header-anchor" href="#算術擴展" aria-label="Permalink to “算術擴展”">​</a></h4><p>Bash 可以進行整型的數學計算，但是比較繁瑣（你一會兒將看到）。數字擴展的語法是 <code>$((arithmetic-expression))</code> ，分別用兩個括號來打開和關閉表達式。算術擴展在 shell 程序或腳本中類似命令替換；表達式結算後的結果替換了表達式，用於 shell 後續的計算。</p><p>我們再用一個簡單的用法來開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo $((1+1))</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=5 ; Var2=7 ; Var3=$((Var1*Var2)) ; echo &quot;Var 3 = $Var3&quot;</span></span>
<span class="line"><span>Var 3 = 35</span></span></code></pre></div><p>下面的除法結果是 0，因為表達式的結果是一個小於 1 的整型數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ Var1=5 ; Var2=7 ; Var3=$((Var1/Var2)) ; echo &quot;Var 3 = $Var3&quot;</span></span>
<span class="line"><span>Var 3 = 0</span></span></code></pre></div><p>這是一個我經常在腳本或 CLI 程序中使用的一個簡單的計算，用來查看在 Linux 主機中使用了多少虛擬內存。 <code>free</code> 不提供我需要的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ RAM=\`free | grep ^Mem | awk &#39;{print $2}&#39;\` ; Swap=\`free | grep ^Swap | awk &#39;{print $2}&#39;\` ; echo &quot;RAM = $RAM and Swap = $Swap&quot; ; echo &quot;Total Virtual memory is $((RAM+Swap))&quot; ;</span></span>
<span class="line"><span>RAM = 4037080 and Swap = 6291452</span></span>
<span class="line"><span>Total Virtual memory is 10328532</span></span></code></pre></div><p>我使用 \` 字符來劃定用作命令替換的界限。</p><p>我用 Bash 算術擴展的場景主要是用腳本檢查系統資源用量後基於返回的結果選擇一個程序運行的路徑。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文是 Bash 編程語言系列的第二篇，探討了 Bash 中文件、字符串、數字和各種提供流程控制邏輯的邏輯操作符還有不同種類的 shell 擴展。</p><hr>`,115)),t("p",null,[s[12]||(s[12]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/19/10/programming-bash-logical-operators-shell-expansions"},{default:n(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/19/10/programming-bash-logical-operators-shell-expansions",-1)])]),_:1})]),t("p",null,[s[17]||(s[17]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[13]||(s[13]=[e("David Both",-1)])]),_:1}),s[18]||(s[18]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),i(a,{href:"https://github.com/lxbwolf"},{default:n(()=>[...s[15]||(s[15]=[e("lxbwolf",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const v=d(c,[["render",h]]);export{y as __pageData,v as default};
